593: fn rewrite_param(param: Param, component: &Component) -> Param {
594:     match param {
595:         Param::Typed(name, mut qualified) => {
596:             if qualified.namespace.is_none() && component.names.types.contains(&qualified.name) {
597:                 qualified.name = prefix(&component.alias, &qualified.name);
598:             }
